void generate(long long x, int depth) {
    long long tmp = ((c1++ - x) % 998244353 + 998244353) % 998244353;
    sums[depth] = (sums[depth] + tmp) % 1000000007;
    buckets[depth].push_back(tmp);
    if (depth == 6) return;
